-- Rollback for List Groups feature.
-- Idempotent (IF EXISTS guards). Drops trigger + function before table; drops
-- group_id column from np_lists; drops the np_list_groups table last.

-- Trigger + function
DROP TRIGGER IF EXISTS set_np_list_groups_updated_at ON public.np_list_groups;
DROP FUNCTION IF EXISTS update_np_list_groups_updated_at();

-- RLS policies on np_list_groups
DROP POLICY IF EXISTS "Users can delete their own groups" ON public.np_list_groups;
