DROP POLICY IF EXISTS "Users can create their own groups" ON public.np_list_groups;
DROP POLICY IF EXISTS "Users can view their own groups" ON public.np_list_groups;

-- Drop FK column on np_lists (does not affect existing rows beyond losing the FK reference)
ALTER TABLE public.np_lists DROP COLUMN IF EXISTS group_id;

-- Drop the table
DROP TABLE IF EXISTS public.np_list_groups;
